    // Build condensation DAG
    vector<vector<int>> dag(C), rdag(C);
    vector<int> indeg(C, 0);
    vector<unordered_set<int>> seen(C);
    for (auto [u,v] : edges) {
        int cu = comp[u], cv = comp[v];
        if (cu != cv && !seen[cu].count(cv)) {
            seen[cu].insert(cv);
            dag[cu].push_back(cv);
            rdag[cv].push_back(cu);
            indeg[cv]++;
        }
    }

    // Find nontrivial SCCs
    vector<int> big;
    for (int c = 0; c < C; ++c) {
        if ((int)comps[c].size() > 1) big.push_back(c);
    }

    // In this graph there can be at most one nontrivial SCC.
    if ((int)big.size() > 1) {
        cout << "NO\n";
        return 0;
    }

    vector<int> grundy(N, -1);
    vector<int> compValue(C, -1); // for trivial SCCs only

    // Topological order of condensation
    queue<int> q;
    vector<int> indeg2 = indeg;
    for (int c = 0; c < C; ++c) if (indeg2[c] == 0) q.push(c);
    vector<int> topo;
    while (!q.empty()) {
        int c = q.front(); q.pop();
        topo.push_back(c);
        for (int to : dag[c]) if (--indeg2[to] == 0) q.push(to);
    }
    reverse(topo.begin(), topo.end()); // reverse topological: successors first

    int cycComp = big.empty() ? -1 : big[0];

    // Solve all trivial SCCs not depending on cycComp unknown? We can process all DAG nodes except cycComp,
    // provided all outgoing component values are known. That means components reaching cycComp cannot be solved yet.
    // We'll first solve components that do not reach cycComp by reverse topo skipping unresolved.
    vector<int> resolvedComp(C, 0);

    bool progress = true;
    while (progress) {
        progress = false;
        for (int c : topo) {
            if (resolvedComp[c] || c == cycComp) continue;
            if ((int)comps[c].size() != 1) continue;
            int v = comps[c][0];
            bool ok = true;
            vector<int> vals;
            for (int to : g[v]) {
                int ct = comp[to];
                if (ct == c) continue;
                if (!resolvedComp[ct]) { ok = false; break; }
                vals.push_back(compValue[ct]);
            }
            if (!ok) continue;
            sort(vals.begin(), vals.end());
            vals.erase(unique(vals.begin(), vals.end()), vals.end());
            int gv = mex_from_sorted_unique(vals);
            grundy[v] = gv;
            compValue[c] = gv;
            resolvedComp[c] = 1;
            progress = true;
        }
    }

    if (cycComp == -1) {
        // Entire graph is DAG; all should be resolved.
        for (int c = 0; c < C; ++c) {
            if (!resolvedComp[c]) {
                cout << "NO\n";
                return 0;
            }
        }
        cout << "YES\n";
        return 0;
    }

    // cycComp must be a directed cycle.
    auto &cycVerts = comps[cycComp];
    int K = cycVerts.size();

    // Map vertex -> its unique outgoing neighbor inside cycComp
    unordered_map<int,int> idx;
    idx.reserve(K * 2);
    for (int i = 0; i < K; ++i) idx[cycVerts[i]] = i;

    vector<int> nxt(K, -1), prv(K, -1);
    for (int i = 0; i < K; ++i) {
        int v = cycVerts[i];
        for (int to : g[v]) {
            if (comp[to] == cycComp) {
                if (nxt[i] != -1) {
                    cout << "NO\n";
                    return 0;
                }
                nxt[i] = idx[to];
            }
        }
    }
    for (int i = 0; i < K; ++i) {
        if (nxt[i] == -1) {
            cout << "NO\n";
            return 0;
        }
        if (prv[nxt[i]] != -1) {
            cout << "NO\n";
            return 0;
        }
        prv[nxt[i]] = i;
    }
    for (int i = 0; i < K; ++i) {
        if (prv[i] == -1) {
            cout << "NO\n";
            return 0;
        }
    }

    // Arrange in cycle order v0 -> v1 -> ... -> vK-1 -> v0
    vector<int> ord(K);
    ord[0] = 0;
    for (int i = 1; i < K; ++i) ord[i] = nxt[ord[i-1]];
    if (nxt[ord[K-1]] != ord[0]) {
        cout << "NO\n";
        return 0;
    }
    vector<int> pos(K);
    for (int i = 0; i < K; ++i) pos[ord[i]] = i;

    vector<int> a(K), b(K);

    // External values for each cycle vertex must already be resolved.
    for (int t = 0; t < K; ++t) {
        int id = ord[t];
        int v = cycVerts[id];
        vector<int> vals;
        for (int to : g[v]) {
            if (comp[to] == cycComp) continue;
            int ct = comp[to];
            if (!resolvedComp[ct]) {
                cout << "NO\n";
                return 0;
            }
            vals.push_back(compValue[ct]);
        }
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        a[t] = mex_from_sorted_unique(vals);
        vals.push_back(a[t]);
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        b[t] = mex_from_sorted_unique(vals);
    }

    auto solve_cycle = [&](int x0, vector<int>& out)->bool{
        vector<int> x(K, -1);
        x[0] = x0;
        // x[i-1] = f_{i-1}(x[i]) for i=1..K-1, and x[K-1] = f_{K-1}(x[0])
        x[K-1] = (x[0] == a[K-1] ? b[K-1] : a[K-1]);
        for (int i = K-2; i >= 1; --i) {
            x[i] = (x[i+1] == a[i] ? b[i] : a[i]);
        }
        int check0 = (x[1] == a[0] ? b[0] : a[0]);
        if (check0 != x[0]) return false;
        out = x;
        return true;
    };

    vector<int> cycAns;
    bool ok = solve_cycle(a[0], cycAns) || solve_cycle(b[0], cycAns);
    if (!ok) {
        cout << "NO\n";
        return 0;
    }

    for (int t = 0; t < K; ++t) {
        grundy[cycVerts[ord[t]]] = cycAns[t];
    }
    resolvedComp[cycComp] = 1;

    // Now solve remaining trivial SCCs that depended on cycle
    progress = true;
    while (progress) {
        progress = false;
        for (int c : topo) {
            if (resolvedComp[c]) continue;
            if ((int)comps[c].size() != 1) continue;
            int v = comps[c][0];
            bool ok2 = true;
            vector<int> vals;
            for (int to : g[v]) {
                int ct = comp[to];
                if (ct == c) continue;
                if (!resolvedComp[ct]) { ok2 = false; break; }
                int val = (ct == cycComp ? grundy[to] : compValue[ct]);
                vals.push_back(val);
            }
            if (!ok2) continue;
            sort(vals.begin(), vals.end());
            vals.erase(unique(vals.begin(), vals.end()), vals.end());
            int gv = mex_from_sorted_unique(vals);
            grundy[v] = gv;
            compValue[c] = gv;
            resolvedComp[c] = 1;
            progress = true;
        }
    }

    for (int c = 0; c < C; ++c) {
        if (!resolvedComp[c]) {
            cout << "NO\n";
            return 0;
        }
    }

    // Final verification
    for (int v = 0; v < N; ++v) {
        vector<int> vals;
        for (int to : g[v]) vals.push_back(grundy[to]);
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        int m = mex_from_sorted_unique(vals);
        if (m != grundy[v]) {
            cout << "NO\n";
            return 0;
        }
    }

    cout << "YES\n";
    return 0;
}

