import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        int[] to = new int[N];
        int[] indeg = new int[N];
        List<Integer>[] rev = new ArrayList[N];
        for (int i = 0; i < N; i++) rev[i] = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            int x = fs.nextInt() - 1;
            to[i] = x;
            indeg[x]++;
            rev[x].add(i);
        }

        // Remove tree parts, keep only cycle vertices.
        boolean[] removed = new boolean[N];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < N; i++) {
            if (indeg[i] == 0) q.add(i);
        }

        while (!q.isEmpty()) {
            int v = q.poll();
            removed[v] = true;
            int u = to[v];
            indeg[u]--;
            if (indeg[u] == 0) q.add(u);
        }

        // Grundy-like value for removed vertices, processed from leaves upward.
        int[] val = new int[N];
        boolean[] done = new boolean[N];

        // DFS from cycle nodes into reverse trees to compute values bottom-up.
        for (int i = 0; i < N; i++) {
            if (!removed[i]) {
                for (int child : rev[i]) {
                    if (removed[child] && !done[child]) {
                        computeTree(child, rev, removed, val, done);
                    }
                }
            }
        }

        // For each cycle, try two possibilities for one chosen node.
        boolean[] visCycle = new boolean[N];
        for (int i = 0; i < N; i++) {
            if (removed[i] || visCycle[i]) continue;

            List<Integer> cyc = new ArrayList<>();
            int cur = i;
            do {
                visCycle[cur] = true;
                cyc.add(cur);
                cur = to[cur];
            } while (cur != i);

            int k = cyc.size();
            int[] base = new int[k]; // mex of non-cycle children only
            for (int idx = 0; idx < k; idx++) {
                int v = cyc.get(idx);
                base[idx] = mexExcludingCycle(v, rev, removed, val);
            }

            if (!checkCycle(cyc, base, val, to)) {
                System.out.println("IMPOSSIBLE");
                return;
            }
        }

        System.out.println("POSSIBLE");
    }

    static void computeTree(int root, List<Integer>[] rev, boolean[] removed, int[] val, boolean[] done) {
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        ArrayDeque<Integer> order = new ArrayDeque<>();
        stack.push(root);
        done[root] = true;

        while (!stack.isEmpty()) {
            int v = stack.pop();
            order.push(v);
            for (int ch : rev[v]) {
                if (removed[ch] && !done[ch]) {
                    done[ch] = true;
                    stack.push(ch);
                }
            }
        }

        while (!order.isEmpty()) {
            int v = order.pop();
            boolean[] seen = new boolean[rev[v].size() + 2];
            for (int ch : rev[v]) {
                if (removed[ch]) {
                    int x = val[ch];
                    if (x < seen.length) seen[x] = true;
                }
            }
            int mex = 0;
            while (mex < seen.length && seen[mex]) mex++;
            val[v] = mex;
        }
    }

    static int mexExcludingCycle(int v, List<Integer>[] rev, boolean[] removed, int[] val) {
        boolean[] seen = new boolean[rev[v].size() + 2];
        for (int ch : rev[v]) {
            if (removed[ch]) {
                int x = val[ch];
                if (x < seen.length) seen[x] = true;
            }
        }
        int mex = 0;
        while (mex < seen.length && seen[mex]) mex++;
        return mex;
    }

    static boolean checkCycle(List<Integer> cyc, int[] base, int[] val, int[] to) {
        int k = cyc.size();

        // Let a0 be value of cyc[0].
        // Then for i=1..k-1, ai = mex(base[i] union {a(i-1)})
        // Finally must satisfy a0 = mex(base[0] union {a(k-1)}).
        // In a functional graph this is enough to try a0 = base[0] and a0 = next candidate.
        int cand1 = base[0];
        if (simulate(cyc, base, val, cand1)) return true;

        int cand2 = cand1 + 1;
        if (simulate(cyc, base, val, cand2)) return true;

        return false;
    }

    static boolean simulate(List<Integer> cyc, int[] base, int[] val, int firstVal) {
        int k = cyc.size();
        int[] a = new int[k];
        a[0] = firstVal;

        for (int i = 1; i < k; i++) {
            a[i] = mexWithOne(base[i], a[i - 1]);
        }

        int required = mexWithOne(base[0], a[k - 1]);
        if (required != a[0]) return false;

        for (int i = 0; i < k; i++) {
            val[cyc.get(i)] = a[i];
        }
        return true;
    }

    static int mexWithOne(int baseMex, int extra) {
        // Base children contain all 0..baseMex-1 and do not contain baseMex.
        // Add one extra value "extra".
        if (extra == baseMex) return baseMex + 1;
        return baseMex;
    }
}
